<div id="wrapper"><div class="content sccc-app"><div class="sccc-page-head"><div><h3><?= _l('sccc_recordings') ?></h3><p class="text-muted"><?= _l('sccc_recordings_subtitle') ?></p></div></div><?php $rows=$this->db->order_by('id','DESC')->limit(200)->get(db_prefix().'sccc_recordings')->result_array();?><div class="sccc-card"><table class="table"><thead><tr><th>#</th><th><?= _l('sccc_call')?></th><th><?= _l('sccc_duration')?></th><th><?= _l('sccc_date')?></th><th><?= _l('sccc_actions')?></th></tr></thead><tbody><?php foreach($rows as $r){?><tr><td><?= $r['id']?></td><td><?= $r['call_id']?></td><td><?= $r['duration']?>s</td><td><?= html_escape($r['created_at'])?></td><td><a class="btn btn-default btn-sm" href="<?= admin_url('smart_choice_call_center/recording_download/'.$r['id'])?>"><i class="fa fa-download"></i> <?= _l('sccc_download')?></a></td></tr><?php }?></tbody></table></div></div></div><?php init_tail(); ?>